test('HTTP coordinator identity, thread lifecycle, steering, memory and resource settings persist',async t=>{
  const root=await fixture(t);let release;const gate=new Promise(r=>{release=r;});let workerCalls=0;
  const providers=fakeProviders(async({messages})=>{if(messages[0].content.includes('Role: worker')){workerCalls++;if(workerCalls===1)await gate;}return {content:'Recorded response',toolCalls:[]};});
  const app=await createStudioServer({root,seed:false,computer:false,evaluator:false,engineering:false,providers});const {port}=await app.listen({port:0});t.after(async()=>{release();await app.close();});const base=`http://127.0.0.1:${port}`;
  async function api(route,method='GET',body){const r=await fetch(base+route,{method,headers:body?{'content-type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});return {status:r.status,data:await r.json()};}
  const project=(await api('/api/projects','POST',{folderPath:await projectFolder(t),name:'Persistent coordinator',resources:{maxConcurrentAgents:1,maxTasksPerRun:8,maxAutoResumes:0}})).data;assert.ok(project.coordinatorThreadId);const initial=(await api(`/api/projects/${project.id}/threads`)).data;assert.equal(initial.threads.length,1);assert.equal(initial.threads[0].kind,'coordinator');
  const reused=await api(`/api/projects/${project.id}/threads`,'POST',{kind:'coordinator'});assert.equal(reused.data.id,project.coordinatorThreadId);
  const worker=(await api(`/api/projects/${project.id}/threads`,'POST',{kind:'worker',parentThreadId:project.coordinatorThreadId,title:'Thermal trade'})).data;assert.equal(worker.parentThreadId,project.coordinatorThreadId);const started=await api(`/api/threads/${worker.id}/messages`,'POST',{content:'Analyze a physical mechanism'});assert.equal(started.status,202);await eventually(()=>workerCalls===1);const steering=await api(`/api/threads/${worker.id}/steer`,'POST',{content:'Add an explicit failure case'});assert.equal(steering.status,202);assert.equal(steering.data.steering.status,'queued');release();await eventually(()=>app.store.get('runs',started.data.run.id).status==='completed');const detail=(await api(`/api/threads/${worker.id}`)).data;assert.equal(detail.steerings[0].status,'delivered');assert.ok(detail.messages.some(m=>m.content==='Add an explicit failure case'));
  assert.equal(detail.thread.status,'resolved','Successful worker completion is automatic');assert.equal((await api(`/api/threads/${worker.id}`,'PATCH',{status:'resolved'})).data.status,'resolved');assert.equal((await api(`/api/threads/${worker.id}`,'PATCH',{status:'open'})).data.status,'resolved','A historical successful run stays complete until actual new work starts');assert.equal((await api(`/api/threads/${worker.id}`,'PATCH',{status:'invalid'})).status,400);
  const mainMessages=(await api(`/api/threads/${project.coordinatorThreadId}/messages`)).data;assert.equal(mainMessages.childThreads.length,1);assert.ok(mainMessages.messages.some(m=>m.type==='thread.result'&&m.metadata.taskThreadId===worker.id));
  const memory=await api(`/api/projects/${project.id}/memory`,'PUT',{version:0,content:'Decision and source, with unresolved hardware evidence.'});assert.equal(memory.data.version,1);assert.equal((await api(`/api/projects/${project.id}/memory`,'PUT',{version:0,content:'Stale edit'})).status,409);
  assert.equal((await api(`/api/projects/${project.id}`,'PATCH',{resources:{maxConcurrentAgents:5}})).data.resources.maxConcurrentAgents,5);assert.equal((await api(`/api/projects/${project.id}`,'PATCH',{resources:{maxConcurrentAgents:0}})).status,400);assert.equal((await api('/api/threads/missing/steer','POST',{content:'No thread'})).status,404);assert.equal((await api('/api/projects/missing/threads')).status,404);
  await app.close();const reopened=createStore({dataDir:app.store.dataDir,seed:false});assert.equal(reopened.get('projects',project.id).coordinatorThreadId,project.coordinatorThreadId);assert.equal(reopened.get('projects',project.id).memoryVersion,1);assert.equal(reopened.get('projects',project.id).resources.maxConcurrentAgents,5);
});

