test('Manual is the default and separately approves or rejects each project mutation',async t=>{
  const root=await fixture(t);let turns=0,engineeringExecutions=0;const h=harness(root,async()=>{turns++;return turns===1?{content:'Preparing reviewed changes',toolCalls:[{id:'write',name:'write_file',args:{path:'approved.md',content:'Reviewed file',permissionMode:'auto'}},{id:'artifact',name:'create_artifact',args:{name:'rejected.md',content:'Do not save this'}},{id:'model',name:'update_model',args:{nodes:[],links:[],version:0}},{id:'memory',name:'update_project_memory',args:{content:'Approved decision',version:0}},{id:'engineering',name:'run_engineering_model',args:{model:'thermal-control-v1',parameters:{}}}]}:{content:'Recorded both approvals and rejection accurately',toolCalls:[]};},{engineering:{catalog:()=>({tools:[],models:[]}),run:async()=>{engineeringExecutions++;return {scope:'protocol-only',status:'completed'};}}});h.project.resources.maxAutoResumes=0;t.after(()=>h.engine.close());const {run}=h.engine.start({threadId:h.thread.id,content:'Make reviewable changes'});assert.equal(run.permissionMode,'manual');
  const names=['write_file','create_artifact','update_model','update_project_memory','run_engineering_model'];for(const name of names){await eventually(()=>h.store.data.approvals.some(a=>a.status==='pending'&&a.tool===name));const approval=h.store.data.approvals.find(a=>a.status==='pending');assert.equal(approval.threadId,h.thread.id);assert.equal(run.status,'waiting_approval');assert.equal(h.store.data.agents.find(a=>a.runId===run.id).status,'waiting_approval');assert.equal(h.engine.overview(h.thread).executionStatus,'waiting_approval');if(name==='write_file')assert.equal(await fs.stat(path.join(h.store.workspace(h.project.id),'approved.md')).catch(()=>null),null);if(name==='update_model')assert.equal(h.store.data.models.length,0);if(name==='update_project_memory')assert.equal(h.project.memoryVersion,0);if(name==='run_engineering_model')assert.equal(engineeringExecutions,0);h.engine.decideApproval(approval.id,name==='create_artifact'?'reject':'approve');}
  await eventually(()=>run.status==='completed');assert.equal(await fs.readFile(path.join(h.store.workspace(h.project.id),'approved.md'),'utf8'),'Reviewed file');assert.equal(h.store.data.artifacts.length,0);assert.equal(h.store.data.models[0].version,1);assert.equal(h.project.memory,'Approved decision');assert.equal(engineeringExecutions,1);assert.equal(h.store.data.approvals.filter(a=>a.status==='approved').length,4);assert.equal(h.store.data.approvals.find(a=>a.tool==='create_artifact').status,'rejected');
});

test('Auto runs project changes and sandboxed commands while native Computer still needs approval',async t=>{
  const root=await fixture(t);let h,turns=0,shellExecutions=0,nativeExecutions=0,engineeringExecutions=0;const computer={status:()=>({desktop:{available:true,status:'protocol-fixture'}}),action:async(payload,ctx)=>{assert.equal(ctx.permissionMode,'auto');assert.equal(ctx.source,'agent');const approved=await h.engine.requestApproval({runId:ctx.runId,projectId:payload.projectId,tool:'computer_use',args:payload,signal:ctx.signal});if(!approved)throw new Error('Native action rejected');nativeExecutions++;return {ok:true};}};
  h=harness(root,async()=>{turns++;return turns===1?{content:'Scoped automatic work',toolCalls:[{id:'w',name:'write_file',args:{path:'auto.md',content:'Project result'}},{id:'a',name:'create_artifact',args:{name:'auto-result.md',content:'Reviewable result'}},{id:'m',name:'update_model',args:{nodes:[],links:[],version:0}},{id:'p',name:'update_project_memory',args:{content:'A recorded choice',version:0}},{id:'e',name:'run_engineering_model',args:{model:'thermal-control-v1'}},{id:'s',name:'run_command',args:{command:'printf scoped'}},{id:'c',name:'computer_use',args:{action:'desktop.click',args:{x:1,y:1}}}]}:{content:'Routine work and sandboxed command completed; denied native action did not execute.',toolCalls:[]};},{computer,engineering:{catalog:()=>({tools:[],models:[]}),run:async()=>{engineeringExecutions++;return {scope:'protocol-only'};}},commandExecutor:async()=>{shellExecutions++;return {code:0};}});h.project.resources.maxAutoResumes=0;t.after(()=>h.engine.close());const {run}=h.engine.start({permissionMode:'auto',threadId:h.thread.id,content:'Work within the selected project'});await eventually(()=>h.store.data.approvals.some(a=>a.status==='pending'&&a.tool==='computer_use'));assert.equal(h.store.data.approvals.length,1);assert.equal(engineeringExecutions,1);assert.equal(h.store.data.artifacts.length,1);assert.equal(h.project.memoryVersion,1);assert.equal(shellExecutions,1);assert.equal(nativeExecutions,0);h.engine.decideApproval(h.store.data.approvals.find(a=>a.status==='pending').id,'reject');await eventually(()=>run.status==='completed');assert.equal(shellExecutions,1);assert.equal(nativeExecutions,0);assert.equal(h.store.data.approvals.length,1);assert.equal(run.permissionMode,'auto');
});

test('Workers inherit originating-run permission and ignore fabricated permission elevation',async t=>{
  const root=await fixture(t),seen=new Set();const h=harness(root,async({messages,tools})=>{const system=messages[0].content,worker=system.includes('Role: worker');if(worker){assert.ok(system.includes('Run permission mode: manual'));if(!seen.has('worker')){seen.add('worker');return {content:'Worker requests a write',toolCalls:[{id:'w',name:'write_file',args:{path:'worker.md',content:'Requires human approval',permissionMode:'auto'}}]};}return {content:'Worker reports the rejected write',toolCalls:[]};}if(!seen.has('main')){seen.add('main');assert.ok(!Object.hasOwn(tools.find(t=>t.name==='start_thread').parameters.properties,'permissionMode'));return {content:'Starting a scoped worker',toolCalls:[{id:'d',name:'delegate_task',args:{name:'Scoped worker',task:'Prepare a file',permissionMode:'auto'}}]};}return {content:'Coordinator remains responsive',toolCalls:[]};});h.project.resources.maxAutoResumes=0;t.after(()=>h.engine.close());const main=h.engine.start({threadId:h.thread.id,content:'Delegate work with manual review'});await eventually(()=>h.store.data.approvals.some(a=>a.status==='pending'));const child=h.store.data.runs.find(r=>r.source==='delegated');assert.equal(main.run.permissionMode,'manual');assert.equal(child.permissionMode,'manual');assert.equal(h.store.data.approvals.find(a=>a.status==='pending').runId,child.id);assert.equal(await fs.stat(path.join(h.store.workspace(h.project.id),'worker.md')).catch(()=>null),null);h.engine.decideApproval(h.store.data.approvals.find(a=>a.status==='pending').id,'reject');await eventually(()=>child.status==='completed'&&main.run.status==='completed');assert.equal(h.project.lastPermissionMode,'manual');
});

test('User steering cannot elevate a running permission mode and authorizes only the next run',async t=>{
  const root=await fixture(t);let release,entered=false,calls=0;const gate=new Promise(r=>{release=r;});const h=harness(root,async({messages})=>{calls++;const currentUser=messages.filter(m=>m.role==='user').at(-1)?.content||'';if(currentUser.includes('automatic permissions only next run'))assert.ok(messages[0].content.includes('Run permission mode: manual'));if(calls===1){entered=true;await gate;return {content:'Current-run write',toolCalls:[{id:'manual-write',name:'write_file',args:{path:'manual-current.md',content:'Do not write without approval'}}]};}if(currentUser==='Now perform the scoped change'&&!messages.some(m=>m.role==='tool'&&m.tool_call_id==='auto-write')){assert.ok(messages[0].content.includes('Run permission mode: auto'));return {content:'Next-run write',toolCalls:[{id:'auto-write',name:'write_file',args:{path:'auto-next.md',content:'Explicit next-run authorization'}}]};}return {content:'Done',toolCalls:[]};});h.project.resources.maxAutoResumes=0;t.after(async()=>{release();await h.engine.close();});const thread=h.store.createThread(h.project.id,'Change permissions later');const first=h.engine.start({threadId:thread.id,content:'Inspect before changes'});await eventually(()=>entered);const steered=h.engine.steer({threadId:thread.id,content:'Continue; use automatic permissions only next run',permissionMode:'auto'});assert.equal(steered.activePermissionMode,'manual');assert.equal(steered.nextPermissionMode,'auto');assert.equal(steered.permissionModeEffective,'next-run');assert.equal(first.run.permissionMode,'manual');release();await eventually(()=>h.store.data.approvals.some(a=>a.status==='pending'));assert.equal(first.run.permissionMode,'manual');h.engine.decideApproval(h.store.data.approvals.find(a=>a.status==='pending').id,'reject');await eventually(()=>first.run.status==='completed');const next=h.engine.start({threadId:thread.id,content:'Now perform the scoped change'});assert.equal(next.run.permissionMode,'auto');await eventually(()=>next.run.status==='completed');assert.equal(await fs.readFile(path.join(h.store.workspace(h.project.id),'auto-next.md'),'utf8'),'Explicit next-run authorization');assert.equal(await fs.stat(path.join(h.store.workspace(h.project.id),'manual-current.md')).catch(()=>null),null);assert.equal(h.store.data.approvals.length,1);
});

test('HTTP requires a safe folder for every new-project route and exposes locked run permissions',async t=>{
  const root=await fixture(t),folder=await projectFolder(t),other=await projectFolder(t);await fs.writeFile(path.join(folder,'original.md'),'Existing project input');
  const app=await createStudioServer({root,seed:false,computer:false,evaluator:false,engineering:false,providers:fakeProviders(async()=>({content:'Read-only response',toolCalls:[]}))});const {port}=await app.listen({port:0});t.after(()=>app.close());const base=`http://127.0.0.1:${port}`;
  async function api(route,method='GET',body){const r=await fetch(base+route,{method,headers:body?{'content-type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});return {status:r.status,data:await r.json()};}
  assert.equal((await api('/api/health')).data.displayName,'Manta');assert.equal((await api('/api/health')).data.app,'mbse-studio');assert.equal((await api('/api/health')).data.version,JSON.parse(await fs.readFile(new URL('../package.json',import.meta.url),'utf8')).version);
  for(const body of [{name:'Missing folder'},{name:'Relative',folderPath:'relative'},{name:'Whole disk',folderPath:'/'},{name:'Home',folderPath:os.homedir()},{name:'Application source',folderPath:root},{name:'Application data',folderPath:path.join(root,'.local')}])assert.equal((await api('/api/projects','POST',body)).status,400);
  assert.equal(app.store.data.projects.length,0);assert.equal((await api('/api/benchmarks/nos3-351/start','POST',{})).status,400);assert.equal(app.store.data.projects.length,0);
  const created=await api('/api/projects','POST',{name:'Bound project',folderPath:folder});assert.equal(created.status,201);const project=created.data;assert.equal(project.folderPath,await fs.realpath(folder));assert.equal((await api(`/api/projects/${project.id}`)).data.folderPath,project.folderPath);assert.equal((await api(`/api/projects/${project.id}`,'PATCH',{folderPath:folder,description:'Same binding'})).status,200);assert.equal((await api(`/api/projects/${project.id}`,'PATCH',{folderPath:other})).status,400);
  const imported=await api('/api/benchmarks/nos3-351/start','POST',{projectId:project.id});assert.equal(imported.status,201);assert.equal(imported.data.project.id,project.id);assert.equal(await fs.readFile(path.join(folder,'original.md'),'utf8'),'Existing project input');assert.ok((await fs.readFile(path.join(folder,'task.json'),'utf8')).includes('nos3-351'));
  const first=await api(`/api/threads/${project.coordinatorThreadId}/messages`,'POST',{content:'Inspect the imported task'});assert.equal(first.status,202);assert.equal(first.data.run.permissionMode,'manual');await eventually(()=>app.store.get('runs',first.data.run.id).status==='completed');const second=await api(`/api/threads/${project.coordinatorThreadId}/messages`,'POST',{content:'Perform scoped work',permissionMode:'auto'});assert.equal(second.data.run.permissionMode,'auto');await eventually(()=>app.store.get('runs',second.data.run.id).status==='completed');assert.equal((await api(`/api/projects/${project.id}`)).data.lastPermissionMode,'auto');assert.equal((await api(`/api/threads/${project.coordinatorThreadId}/messages`,'POST',{content:'No arbitrary mode',permissionMode:'elevated'})).status,400);
});

test('A model changed while manual approval is pending cannot be overwritten or duplicated',async t=>{
  const root=await fixture(t);let release;const gate=new Promise(r=>{release=r;});const store=createStore({dataDir:path.join(root,'.local'),seed:false}),project=store.createProject({name:'Concurrent review'}),runtime=createToolRuntime({store,emit:()=>{},requestApproval:async()=>gate});const ctx={projectId:project.id,isCoordinator:true};const update=runtime.execute('update_model',{nodes:[],links:[],version:0},ctx);await new Promise(r=>setTimeout(r,0));store.data.models.push({projectId:project.id,nodes:[{id:'newer',type:'requirement',name:'Human edit while waiting'}],links:[],version:1});release(true);await assert.rejects(update,/changed while awaiting approval/);assert.equal(store.data.models.length,1);assert.equal(store.data.models[0].nodes[0].id,'newer');
});

test('Shared presentation is read-only and thread history retains older-run activity with explicit gaps',async t=>{
  const root=await fixture(t);await fs.mkdir(path.join(root,'shared'));await fs.writeFile(path.join(root,'shared/run-presentation.mjs'),await fs.readFile(new URL('../shared/run-presentation.mjs',import.meta.url),'utf8'));await fs.writeFile(path.join(root,'shared/private.mjs'),'private source must not be served');
  const app=await createStudioServer({root,seed:false,computer:false,evaluator:false,engineering:false});const {port}=await app.listen({port:0});t.after(()=>app.close());const base=`http://127.0.0.1:${port}`,project=app.store.createProject({name:'Long-lived history'}),threadId=project.coordinatorThreadId,stamp=n=>new Date(Date.UTC(2026,9,22,0,0,0,n)).toISOString();
  const module=await fetch(base+'/shared/run-presentation.mjs');assert.equal(module.status,200);assert.match(module.headers.get('content-type'),/javascript/);assert.match(await module.text(),/export function buildRunPresentation/);assert.equal((await fetch(base+'/shared/private.mjs')).status,404);assert.equal((await fetch(base+'/shared/run-presentation.mjs',{method:'POST'})).status,405);assert.equal((await fetch(base+'/server/store.mjs')).status,404);
  const old={id:'run_no_retained_events',projectId:project.id,threadId,status:'completed',createdAt:stamp(-120000),startedAt:stamp(-119000),finishedAt:stamp(-118000)},first={id:'run_history_first',projectId:project.id,threadId,status:'completed',createdAt:stamp(0),startedAt:stamp(1000),finishedAt:stamp(2000)},second={id:'run_history_second',projectId:project.id,threadId,status:'completed',createdAt:stamp(3000),startedAt:stamp(4000),finishedAt:stamp(5000)};app.store.data.runs.push(old,first,second);
  for(const [run,count,start]of [[first,250,1000],[second,100,4000]]){app.store.data.events.push({id:run.id+'-start',projectId:project.id,runId:run.id,type:'run.started',createdAt:stamp(start),data:{}});for(let i=0;i<count;i++){app.store.data.events.push({id:run.id+'-tool-start-'+i,projectId:project.id,runId:run.id,type:'tool.started',createdAt:stamp(start+i*2+1),data:{tool:'read_file',agentId:run.id,args:{path:'source-'+i+'.md'}}});app.store.data.events.push({id:run.id+'-tool-end-'+i,projectId:project.id,runId:run.id,type:'tool.completed',createdAt:stamp(start+i*2+2),data:{tool:'read_file',agentId:run.id,result:{content:'Recorded source'}}});}app.store.data.events.push({id:run.id+'-end',projectId:project.id,runId:run.id,type:'run.finished',createdAt:run.finishedAt,data:{status:'completed'}});}
  app.store.message(threadId,'user','Keep this steering visible',first.id,{type:'thread.steering',metadata:{delivery:'delivered'}});app.store.data.approvals.push({id:'approval_history',runId:first.id,projectId:project.id,tool:'write_file',status:'pending'});app.store.save();
  const detail=await fetch(base+'/api/threads/'+threadId).then(r=>r.json());assert.equal(detail.events.length,704);assert.ok(detail.events.some(e=>e.id===first.id+'-tool-start-0'));assert.equal(detail.eventHistory.perRun[first.id].retainedCount,502);assert.equal(detail.eventHistory.perRun[first.id].complete,true);assert.equal(detail.eventHistory.perRun[first.id].truncated,false);assert.equal(detail.eventHistory.perRun[old.id].truncated,true);assert.equal(detail.eventHistory.perRun[old.id].totalCount,null);assert.equal(detail.eventHistory.truncated,true);assert.equal(detail.messages[0].content,'Keep this steering visible');assert.equal(detail.approvals[0].id,'approval_history');
});
